text:
.button {
  position: absolute;
  inset-inline-end: 0;
  inset-block: 0;
  color: inherit;
  display: flex;
  flex-direction: column;
  justify-content: space-around;

  &.button-flat.icon-button {
    padding: 4px;
    margin: 0;

    &:focus-visible {
      outline-offset: -1px;

      @media (-moz-windows-accent-color-in-titlebar) {
        outline-offset: -4px;
      }
    }
  }
}

#search-button {
  display: var(--search-button-show);
}

div {
  display: none;
  position: absolute;
  pointer-events: none;
  color: var(--search-field-placeholder);
  inset-inline-start: 1ch;
  inset-inline-end: var(--search-buttons-padding);
  flex-direction: column;
  justify-content: space-around;
  text-overflow: clip;
  overflow: hidden;
  white-space: nowrap;
  inset-block: 0;

  input:placeholder-shown + & {
    display: flex;
  }
